import { createClientFromRequest } from 'npm:@base44/sdk@0.8.54';
import { errorResponse, json, readJson, relationToAthlete } from '../../shared/coachAuth.ts';
import { validateMetric, validateReadiness } from '../../shared/metrics.ts';
import { oneOf, requireId } from '../../shared/validation.ts';

// Records a performance test result or a wellness check-in. Athletes record
// their own; coaches record for actively linked athletes. Results are never
// generated by the app, and earlier results are kept as history.
export default async function (req: Request) {
  try {
    const base44 = createClientFromRequest(req);
    const user = await base44.auth.me();
    if (!user) return json({ error: 'Unauthorized' }, 401);

    const body = await readJson(req);
    const kind = oneOf(body.kind ?? 'metric', ['metric', 'readiness'] as const, 'kind');
    const athleteId = body.athlete_id === undefined ? user.id : requireId(body.athlete_id, 'athlete_id');

    const relation = await relationToAthlete(base44, user, athleteId);
    if (!relation) return json({ error: 'You do not have access to this athlete' }, 403);
    if (kind === 'readiness' && relation !== 'self') {
      return json({ error: 'Wellness check-ins are recorded by the athlete' }, 403);
    }

    const db = base44.asServiceRole.entities;
    const common = {
      user_id: athleteId,
      coach_id: relation === 'coach' ? user.id : undefined,
      recorded_by_id: user.id,
      source: relation === 'self' ? 'athlete' : relation,
    };

    if (kind === 'readiness') {
      const r = validateReadiness(body);
      const existing = await db.ReadinessEntry.filter({ user_id: athleteId, date: r.date }, { limit: 1 });
      const record = existing.items?.[0]
        ? await db.ReadinessEntry.update(existing.items[0].id, { ...r, recorded_by_id: user.id })
        : await db.ReadinessEntry.create({ ...common, ...r });
      return json({ record });
    }

    const m = validateMetric(body);
    const record = await db.PerformanceMetric.create({ ...common, ...m });
    return json({ record });
  } catch (error) {
    return errorResponse(error);
  }
}
